excels.excel:

EXPORT WITH SHEET="广告投产分析", HEADER=true,
    MAPPING={"a":"门店","b":"广告投入","c":"销售额","d":"投产比"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"0.00"},
    FORMULAS={
        D2:'C2/B2',D3:'C3/B3',D4:'C4/B4',D5:'C5/B5',
        B6:'SUM(B2:B5)',C6:'SUM(C2:C5)',D6:'C6/B6'
    },
    STYLE={ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}},
    GRAPH={TYPE=SCATTER, TITLE="广告投产散点图", CATEGORY_AXIS=门店, VALUE_AXIS=销售额,
           CATEGORIES=["门店A","门店B","门店C","门店D"],
           SERIES=[
               {NAME=销售额, DATA=[300000,440000,720000,810000]}
           ]}
